package com.yuewei.plm.module.moldreference;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class PhoneIdentityHistoryTest {
    Map<String,Object> brand(long id,String name,String... aliases){return new LinkedHashMap<>(Map.of("brandId",id,"name",name,"status","enabled","aliases",List.of(aliases)));}
    Map<String,Object> code(long id,String value,String name){return Map.of("codeItemId",id,"codeValue",value,"codeName",name,"status","enabled");}
    @Test void originalsRemainAnchorsAndNetworkVariantsRemainDistinct(){var b=brand(1,"Samsung","SM");var result=PhoneIdentityHistory.preview(List.of(b),List.of(),List.of(code(1,"0001","SM A57 4G"),code(2,"0002","Samsung Galaxy A57 5G")));assertThat(result.counts().get("initialize")).isEqualTo(2L);assertThat(result.decisions()).extracting(PhoneIdentityHistory.Decision::codeValue).containsExactly("0001","0002");assertThat(result.decisions()).extracting(PhoneIdentityHistory.Decision::identityKey).containsExactly("a57 4g","a57 5g");}
    @Test void normalizedIdentityWithDifferentCodesNeverChoosesFirst(){var b=brand(1,"Samsung","SM");var result=PhoneIdentityHistory.preview(List.of(b),List.of(),List.of(code(1,"0001","SM A57 5G"),code(2,"0002"," Samsung   Galaxy A57 5G ")));assertThat(result.decisions()).extracting(PhoneIdentityHistory.Decision::reason).containsExactly("multiple_code_identity","multiple_code_identity");}
    @Test void combinationsHoleScopesOtherDevicesAndUnknownSuffixesStayForReview(){var brands=List.of(brand(1,"Samsung","SM"),brand(2,"Apple","IP","iPhone"));var result=PhoneIdentityHistory.preview(brands,List.of(),List.of(code(1,"0001","SM A57/A58"),code(2,"0002","SM A57 Agujero fino"),code(3,"0003","Apple iPad 18"),code(4,"0004","SM A57 Nuevo"),code(5,"0005","SM S777")));assertThat(result.decisions()).extracting(PhoneIdentityHistory.Decision::reason).containsExactly("combined_model","hole_scope","other_device","model_or_suffix_unrecognized","model_or_suffix_unrecognized");}
    @Test void anExistingMemberCannotBeReassignedToAnotherHistoricalCode(){var b=brand(1,"Apple","IP","iPhone");var phone=Map.<String,Object>of("phoneModelId",3L,"brandId",1L,"modelName","iPhone 18 Pro","aliases",List.of(),"codeItemId",8L);var result=PhoneIdentityHistory.preview(List.of(b),List.of(phone),List.of(code(8,"0008","IP 18 Pro"),code(9,"0009","Apple iPhone 18 Pro")));assertThat(result.decisions().get(0).action()).isEqualTo("existing");assertThat(result.decisions().get(1).reason()).isEqualTo("existing_identity_other_code");}
    @Test void onlyUniqueVerifiedMesSourcePrefixesBecomeAliases(){var b=brand(1,"Motorola");b.putAll(Map.of("sourceSystem","mes","sourceRecordId","7","sourceSnapshot",Map.of("id",7,"brand_code","MT")));var result=PhoneIdentityHistory.withVerifiedSourceAliases(List.of(b));assertThat(result.get(0).get("aliases")).isEqualTo(List.of("MT"));assertThat(b.get("aliases")).isEqualTo(List.of());b.put("sourceRecordId","99");assertThat(PhoneIdentityHistory.withVerifiedSourceAliases(List.of(b)).get(0).get("aliases")).isEqualTo(List.of());}
    @Test void verifiedPrefixCannotClaimAnotherBrandOrASecondSource(){var b=brand(1,"Motorola");b.putAll(Map.of("sourceSystem","mes","sourceRecordId","7","sourceSnapshot",Map.of("id",7,"brand_code","MT")));var second=brand(2,"Other","MT");assertThat(PhoneIdentityHistory.withVerifiedSourceAliases(List.of(b,second)).get(0).get("aliases")).isEqualTo(List.of());second=brand(2,"Other");second.putAll(Map.of("sourceSystem","mes","sourceRecordId","8","sourceSnapshot",Map.of("id",8,"brand_code","MT")));assertThat(PhoneIdentityHistory.withVerifiedSourceAliases(List.of(b,second))).extracting(v->v.get("aliases")).containsOnly(List.of());}
}
